const ingressData = $('Persist Ticket & Structured Ingress').first().json;
const ticketId = ingressData.ticket_id;
const clientName = ingressData.client_name;
const clientPhone = ingressData.client_phone;
const location = ingressData.location || 'Unknown';
const rawMessage = $('Inbound Lead Webhook').first().json.body.message || '';

const httpInput = $input.first().json;
let isValid = false;
let parsed = null;
let errorReason = null;

if (httpInput.error) {
  errorReason = 'HTTP inference failure: ' + (httpInput.error.message || JSON.stringify(httpInput.error));
} else {
  try {
    let raw = httpInput.response;
    if (typeof raw === 'string') {
      raw = JSON.parse(raw);
    }
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
      throw new Error('Response is not a JSON object');
    }

    const allowedKeys = ['urgency', 'trade_category', 'requires_urgent_review', 'incident_summary'];
    const keys = Object.keys(raw);
    const extraKeys = keys.filter(k => !allowedKeys.includes(k));
    if (extraKeys.length > 0) {
      throw new Error('Extra forbidden keys rejected: ' + extraKeys.join(', '));
    }

    const missingKeys = allowedKeys.filter(k => !keys.includes(k));
    if (missingKeys.length > 0) {
      throw new Error('Missing required keys: ' + missingKeys.join(', '));
    }

    const validUrgencies = ['CRITICAL', 'HIGH', 'STANDARD'];
    if (!validUrgencies.includes(raw.urgency)) {
      throw new Error('Invalid urgency enum: ' + raw.urgency);
    }

    const validTrades = ['COMMERCIAL_REFRIGERATION', 'COMMERCIAL_HVAC', 'PLUMBING', 'GENERAL'];
    if (!validTrades.includes(raw.trade_category)) {
      throw new Error('Invalid trade_category enum: ' + raw.trade_category);
    }

    if (typeof raw.requires_urgent_review !== 'boolean') {
      throw new Error('requires_urgent_review must be boolean, got ' + typeof raw.requires_urgent_review);
    }

    if (typeof raw.incident_summary !== 'string' || raw.incident_summary.trim().length < 10 || raw.incident_summary.trim().length > 300) {
      throw new Error('incident_summary must be a string between 10 and 300 characters');
    }

    parsed = {
      urgency: raw.urgency,
      trade_category: raw.trade_category,
      requires_urgent_review: raw.requires_urgent_review,
      incident_summary: raw.incident_summary.trim()
    };
    isValid = true;
  } catch (e) {
    errorReason = e.message;
  }
}

let classificationStatus = '';
let urgency = '';
let tradeCategory = '';
let requiresUrgentReview = false;
let incidentSummary = '';
let dispatchState = '';
let operatorAlert = null;

if (isValid && parsed) {
  classificationStatus = 'TRIAGE_SUCCESS';
  urgency = parsed.urgency;
  tradeCategory = parsed.trade_category;
  requiresUrgentReview = parsed.requires_urgent_review;
  incidentSummary = parsed.incident_summary;
  dispatchState = 'PENDING_HUMAN_APPROVAL';
  const isUrgent = parsed.urgency === 'CRITICAL' || parsed.urgency === 'HIGH' || parsed.requires_urgent_review;
  const alertPrefix = isUrgent ? 'Urgent intake' : 'Standard service intake';
  operatorAlert = '[DRAFT ALERT - NOT SENT - REQUIRES HUMAN DISPATCH APPROVAL] ' + alertPrefix + ' for ' + clientName + ' (' + location + '): ' + incidentSummary;
} else {
  classificationStatus = 'FALLBACK_MANUAL_REVIEW';
  urgency = 'UNKNOWN';
  tradeCategory = 'UNKNOWN';
  requiresUrgentReview = true;
  incidentSummary = 'Automated classification unavailable. Manual review required.';
  dispatchState = 'MANUAL_REVIEW_REQUIRED';
  operatorAlert = '[FALLBACK ALERT - MANUAL REVIEW REQUIRED] Classification failed: ' + (errorReason || 'Unknown error') + ' | Client: ' + clientName + ' (' + location + ')';
}

return {
  ticket_id: ticketId,
  intake_status: classificationStatus,
  urgency: urgency,
  trade_category: tradeCategory,
  requires_urgent_review: requiresUrgentReview,
  incident_summary: incidentSummary,
  dispatch_state: dispatchState,
  operator_alert_draft: operatorAlert,
  error_reason: errorReason,
  client_name: clientName,
  client_phone: clientPhone,
  location: location
};
